WITH with_windows AS (SELECT *, NTILE(3) OVER (ORDER BY rating DESC, id ASC) AS rating_bucket, NTILE(4) OVER (PARTITION BY city ORDER BY rating DESC, id ASC) AS rating_bucket_2 FROM suppliers) SELECT id, supplier_name, country, city, rating, rating_bucket, rating_bucket_2, CASE WHEN supplier_name RLIKE '^(Global Supply|Tokyo Traders)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS supplier_name_zone FROM with_windows ORDER BY id DESC, rating DESC
